def column_totals(rows):
    if not rows:
        return []
    result = []
    for i in range(len(rows[0])):
        total = 0
        has_numeric = False
        for r in rows:
            if isinstance(r[i], (int, float)):
                total += r[i]
                has_numeric = True
        if has_numeric:
            result.append(total)
        else:
            result.append("")
    return result

